<?php
require __DIR__.'/includes/auth.php';
$id=(int)($_GET['id']??0);
$st=db()->prepare("SELECT b.*,p.name package_name,a.name pickup_area FROM bookings b JOIN packages p ON p.id=b.package_id LEFT JOIN pickup_areas a ON a.id=b.pickup_area_id WHERE b.id=?");
$st->execute([$id]);$b=$st->fetch();if(!$b)exit('Booking not found');
$st=db()->prepare("SELECT * FROM booking_items WHERE booking_id=? ORDER BY id");$st->execute([$id]);$items=$st->fetchAll();
if(($_GET['download']??'')==='1'){
 $lines=[];
 $add=function($s,$size=10,$bold=false)use(&$lines){$s=trim((string)$s);if(function_exists('iconv')){$v=@iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$s);if($v!==false)$s=$v;}$s=preg_replace('/[^\x20-\x7E]/','',$s)??'';foreach(explode("\n",wordwrap($s,86,"\n",true)) as $line)$lines[]=[$line,$size,$bold];};
 $money=fn($v)=>'IDR '.number_format((float)$v,0,',','.');
 $add(site_brand_name(),18,true);$add('BALI, INDONESIA',9);$add(str_repeat('-',86),9);
 $add('BOOKING INVOICE',16,true);$add('Booking Code: '.$b['booking_code'],12,true);$add('Invoice: '.($b['invoice_number']??'-').' | Created: '.($b['created_at']??'-'),9);
 $add(str_repeat('-',86),9);$add('CUSTOMER',11,true);$add('Name: '.$b['customer_name']);$add('Email: '.$b['customer_email']);$add('WhatsApp: '.$b['customer_whatsapp']);
 $add(str_repeat('-',86),9);$add('ACTIVITY DETAILS',11,true);$add('Activity: '.$b['package_name']);$add('Date: '.$b['booking_date'].' | Time: '.substr((string)($b['activity_time']??''),0,5));$add('Guests: '.(int)$b['adults'].' adult(s) / '.(int)$b['children'].' child(ren)');
 $add('Pickup: '.(!empty($b['pickup_required'])?($b['pickup_area']?:'Yes').(!empty($b['hotel_name'])?' - '.$b['hotel_name']:''):'No pickup'));$add('Payment: '.($b['payment_status']??'-').' | '.($b['payment_method']??'-'));
 $add(str_repeat('-',86),9);$add('ITEMS',11,true);foreach($items as $it)$add($it['item_name'].' | Qty '.$it['quantity'].' | '.$money($it['unit_price']).' | '.$money($it['total_price']),9);
 $add(str_repeat('-',86),9);$add('Activity: '.$money($b['activity_price']));$add('Pickup: '.$money($b['pickup_price']));if((float)($b['discount_amount']??0)>0)$add('Discount: -'.$money($b['discount_amount']));$add('TOTAL: '.$money($b['total']),16,true);
 $stream='';$y=790;foreach($lines as $r){if($y<35)break;[$line,$size,$bold]=$r;$line=str_replace(['\\','(',')'],['\\\\','\(','\)'],$line);$font=$bold?'/F2':'/F1';$stream.="BT $font $size Tf 42 $y Td ($line) Tj ET\n";$y-=($size>=15?27:($size>=12?23:17));}
 $objs=[];$objs[]='<< /Type /Catalog /Pages 2 0 R >>';$objs[]='<< /Type /Pages /Kids [3 0 R] /Count 1 >>';$objs[]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>';$objs[]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';$objs[]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>';$objs[]='<< /Length '.strlen($stream)." >>\nstream\n".$stream.'endstream';
 $pdf="%PDF-1.4\n";$offsets=[0];foreach($objs as $i=>$o){$offsets[]=strlen($pdf);$pdf.=($i+1)." 0 obj\n".$o."\nendobj\n";}$xref=strlen($pdf);$pdf.="xref\n0 ".(count($objs)+1)."\n0000000000 65535 f \n";for($i=1;$i<count($offsets);$i++)$pdf.=sprintf("%010d 00000 n \n",$offsets[$i]);$pdf.="trailer\n<< /Size ".(count($objs)+1)." /Root 1 0 R >>\nstartxref\n".$xref."\n%%EOF";
 $filename=preg_replace('/[^A-Za-z0-9._-]/','-',(string)$b['booking_code'])?:'booking-invoice';header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$filename.'.pdf"');header('Content-Length: '.strlen($pdf));header('Cache-Control: private, no-store');echo $pdf;exit;
}
