<!doctype html><html><head><meta charset="utf-8"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><title>Invoice <?=$b['booking_code']?></title><style>body{font-family:'Inter',Arial,sans-serif;color:#111;margin:40px}.invoice{max-width:850px;margin:auto}.head{display:flex;justify-content:space-between;border-bottom:2px solid #111;padding-bottom:20px}.row{display:flex;justify-content:space-between;margin:8px 0}.box{border:1px solid #ddd;padding:18px;margin-top:20px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}@media print{.no-print{display:none}}</style></head><body><div class="invoice"><div class="head"><div><?php $invoiceLogo=setting('site_logo',setting('admin_logo','')); if($invoiceLogo): ?><img src="<?=e(asset_url($invoiceLogo))?>" alt="" style="display:block;max-width:220px;max-height:70px;object-fit:contain;margin-bottom:10px"><?php endif; ?><div><?=e(setting('site_address','Bali, Indonesia'))?></div><div><?=e(setting('site_email',''))?> · <?=e(setting('site_phone',''))?></div></div><div><h2>BOOKING</h2><b><?=e($b['booking_code'])?></b><br>Invoice: <?=e($b['invoice_number']??'—')?><br><?=e($b['created_at'])?></div></div><div class="box"><div class="row"><span>Customer</span><b><?=e($b['customer_name'])?></b></div><div class="row"><span>Email</span><span><?=e($b['customer_email'])?></span></div><div class="row"><span>WhatsApp</span><span><?=e($b['customer_whatsapp'])?></span></div><div class="row"><span>Activity</span><span><?=e($b['package_name'])?></span></div><div class="row"><span>Date</span><span><?=e($b['booking_date'])?></span></div><div class="row"><span>Guests</span><span><?=$b['adults']?> adult / <?=$b['children']?> child</span></div><div class="row"><span>Pickup</span><span><?=e($b['pickup_area']?:'No pickup')?><?= $b['hotel_name']?' · '.e($b['hotel_name']):'' ?></span></div><div class="row"><span>Payment</span><span><?=e($b['payment_status'])?> · <?=e($b['payment_method']??'—')?></span></div></div><table><tr><th>Item</th><th>Qty</th><th>Unit</th><th class="right">Total</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['item_name'])?></td><td><?=$i['quantity']?></td><td><?=rupiah($i['unit_price'])?></td><td class="right"><?=rupiah($i['total_price'])?></td></tr><?php endforeach;?></table><div class="box"><div class="row"><span>Activity</span><span><?=rupiah($b['activity_price'])?></span></div><div class="row"><span>Pickup</span><span><?=rupiah($b['pickup_price'])?></span></div><?php if((float)($b['discount_amount']??0)>0): ?><div class="row"><span>Discount <?=!empty($b['discount_code'])?'('.e($b['discount_code']).')':''?></span><span>-<?=rupiah($b['discount_amount'])?></span></div><?php endif; ?><div class="row"><strong>TOTAL</strong><strong><?=rupiah($b['total'])?></strong></div></div><p class="no-print"><button onclick="window.print()">Print / Save PDF</button> <button onclick="window.close()">Close</button></p></div></body></html>